14	 * params (e.g. `({ id }) => `/v1/users/${id}``).
15	 */
16	type Ctx<P> = { params: Promise<P> }
17	type PathBuilder<P> = string | ((params: P) => string)
18	
19	function respond<T>(res: ApiResponse<T>) {
20	  return NextResponse.json(res, { status: res.success === false ? 400 : 200 })
21	}
22	
23	function resolvePath<P>(buildPath: PathBuilder<P>, params: P): string {
24	  return typeof buildPath === 'function' ? buildPath(params) : buildPath
25	}
26	
27	async function readParams<P>(ctx?: Ctx<P>): Promise<P> {
28	  return ctx?.params ? await ctx.params : ({} as P)
