import { afterEach, describe, expect, it, vi } from 'vitest'

import companyProfileConfig from '@/configs/companyProfileConfig'
import type { CompanyProfileConfig } from '@/configs/companyProfileConfig'
import { renderWithProviders, screen, within } from '@/test/utils'

import BerandaPage from './page'

const CONFIG_MODULE = '@/configs/companyProfileConfig'

function getServiceItems() {
  return within(screen.getByRole('list', { name: 'Layanan' })).getAllByRole('listitem')
}

describe('Beranda page', () => {
  afterEach(() => {
    vi.doUnmock(CONFIG_MODULE)
    vi.resetModules()
  })

  it('renders the organization name and tagline from the config', () => {
    renderWithProviders(<BerandaPage />)

    expect(screen.getByRole('heading', { level: 1, name: companyProfileConfig.organizationName })).toBeInTheDocument()
    expect(screen.getByText(companyProfileConfig.tagline)).toBeInTheDocument()
  })

  it('renders exactly three services with a title and a paragraph each', () => {
    renderWithProviders(<BerandaPage />)

    const items = getServiceItems()

    expect(items).toHaveLength(3)

    items.forEach((item, index) => {
      const service = companyProfileConfig.services[index]

      expect(within(item).getByRole('heading', { level: 3, name: service.title })).toBeInTheDocument()

      const paragraph = within(item).getByText(service.description)

      expect(paragraph.tagName).toBe('P')
    })
  })

  it('links the contact button to /kontak', () => {
    renderWithProviders(<BerandaPage />)

    expect(screen.getByRole('link', { name: 'Kontak' })).toHaveAttribute('href', '/kontak')
  })

  it('renders whatever the config holds instead of hard-coded copy', async () => {
    const alternateConfig: CompanyProfileConfig = {
      organizationName: 'Koperasi Uji Coba Nusantara',
      tagline: 'Tagline pengganti yang hanya ada di test ini.',
      services: [
        { title: 'Layanan Uji Alfa', description: 'Deskripsi uji alfa.' },
        { title: 'Layanan Uji Beta', description: 'Deskripsi uji beta.' },
        { title: 'Layanan Uji Gama', description: 'Deskripsi uji gama.' }
      ],
      about: { paragraphs: ['Paragraf uji.'] },
      team: [{ name: 'Penguji', role: 'Peran uji' }]
    }

    // Per-test module swap: the page is re-imported after the mock is registered so it
    // picks up the alternate values, while the other tests keep the real config.
    vi.resetModules()
    vi.doMock(CONFIG_MODULE, () => ({ default: alternateConfig }))

    const { default: MockedBerandaPage } = await import('./page')

    renderWithProviders(<MockedBerandaPage />)

    expect(screen.getByRole('heading', { level: 1, name: alternateConfig.organizationName })).toBeInTheDocument()
    expect(screen.getByText(alternateConfig.tagline)).toBeInTheDocument()

    const items = getServiceItems()

    expect(items).toHaveLength(3)
    alternateConfig.services.forEach((service, index) => {
      expect(within(items[index]).getByRole('heading', { level: 3, name: service.title })).toBeInTheDocument()
      expect(within(items[index]).getByText(service.description)).toBeInTheDocument()
    })

    expect(screen.queryByText(companyProfileConfig.organizationName)).not.toBeInTheDocument()
    expect(screen.queryByText(companyProfileConfig.tagline)).not.toBeInTheDocument()
    companyProfileConfig.services.forEach(service => {
      expect(screen.queryByText(service.title)).not.toBeInTheDocument()
    })
  })

  it('keeps exactly three services in the config', () => {
    expect(companyProfileConfig.services).toHaveLength(3)

    companyProfileConfig.services.forEach(service => {
      expect(service.title.trim()).not.toBe('')
      expect(service.description.trim()).not.toBe('')
    })
  })
})

