import { describe, expect, it, vi } from 'vitest'

import { getServerSession } from 'next-auth'

import { proxy } from '@/proxy'

import { OPEN_ROUTES, isOpenRoute } from '.'

vi.mock('next-auth', () => ({ getServerSession: vi.fn() }))

const ORIGIN = 'http://localhost:3000'

const signedInSession = { accessToken: 'token-abc', user: { id: 'u-1' } }

const setSession = (session: unknown) => {
  vi.mocked(getServerSession).mockResolvedValue(session as never)
}

const visit = (pathname: string) => proxy(new Request(`${ORIGIN}${pathname}`))

const redirectPath = (res: Response) => {
  const location = res.headers.get('location')

  return location ? new URL(location).pathname : null
}

describe('isOpenRoute', () => {
  it('treats /beranda, /tentang-kami and /kontak as open routes', () => {
    expect(OPEN_ROUTES).toEqual(['/beranda', '/tentang-kami', '/kontak'])
    expect(isOpenRoute('/beranda')).toBe(true)
    expect(isOpenRoute('/tentang-kami')).toBe(true)
    expect(isOpenRoute('/kontak')).toBe(true)
  })

  it('keeps /login, /register, /home and other paths closed', () => {
    for (const pathname of ['/login', '/register', '/home', '/', '/users', '/roles', '/profile']) {
      expect(isOpenRoute(pathname)).toBe(false)
    }
  })

  it('does not open near-miss paths like /kontak-palsu or nested /kontak/x', () => {
    for (const pathname of ['/kontak-palsu', '/kontak/x', '/beranda/', '/tentang-kami/tim', '/Kontak', 'kontak', '']) {
      expect(isOpenRoute(pathname)).toBe(false)
    }
  })
})

describe('proxy on open routes', () => {
  it('lets an anonymous visitor through on an open route', async () => {
    setSession(null)

    for (const pathname of OPEN_ROUTES) {
      const res = await visit(pathname)

      expect(res.status).toBe(200)
      expect(res.headers.get('location')).toBeNull()
    }
  })

  it('does not redirect a signed-in user away from an open route', async () => {
    setSession(signedInSession)

    for (const pathname of OPEN_ROUTES) {
      const res = await visit(pathname)

      expect(res.status).toBe(200)
      expect(res.headers.get('location')).toBeNull()
    }

    // The login-page bounce for signed-in users is unchanged.
    expect(redirectPath(await visit('/login'))).toBe('/home')
    expect(redirectPath(await visit('/register'))).toBe('/home')
  })

  it('still redirects an anonymous visitor on a protected route to /login', async () => {
    setSession(null)

    for (const pathname of ['/home', '/users', '/kontak-palsu', '/kontak/x']) {
      expect(redirectPath(await visit(pathname))).toBe('/login')
    }

    // Anonymous visitors can still reach the login and register pages.
    for (const pathname of ['/login', '/register']) {
      const res = await visit(pathname)

      expect(res.status).toBe(200)
      expect(res.headers.get('location')).toBeNull()
    }
  })

  it('still redirects to /login and clears cookies when a RefreshTokenError session hits an open route', async () => {
    setSession({ ...signedInSession, error: 'RefreshTokenError' })

    for (const pathname of OPEN_ROUTES) {
      const res = await visit(pathname)

      expect(redirectPath(res)).toBe('/login')

      const setCookie = res.headers.get('set-cookie') ?? ''

      expect(setCookie).toContain('next-auth.session-token=')
      expect(setCookie).toContain('__Secure-next-auth.session-token=')
    }
  })
})

