import { NextResponse } from 'next/server'

import { getServerSession } from 'next-auth'

import { authOptions } from './libs/auth'
import { isOpenRoute } from './libs/public-routes'

export async function proxy(request: Request) {
  const session = await getServerSession(authOptions)
  const { pathname } = new URL(request.url)

  const publicRoutes = ['/login', '/register']
  const isPublicRoute = publicRoutes.includes(pathname)

  if (session?.error === 'RefreshTokenError') {
    // Clear the session cookie and redirect — no signOut() needed here
    const response = NextResponse.redirect(new URL('/login', request.url))

    response.cookies.delete('next-auth.session-token')
    response.cookies.delete('__Secure-next-auth.session-token') // for HTTPS

    return response
  }

  // Company-profile pages are open to everyone: anonymous visitors are not sent to
  // /login and signed-in users are not bounced to /home.
  if (isOpenRoute(pathname)) {
    return NextResponse.next()
  }

  if (session?.accessToken && isPublicRoute) {
    return NextResponse.redirect(new URL('/home', request.url))
  }

  if (!session?.accessToken && !isPublicRoute) {
    return NextResponse.redirect(new URL('/login', request.url))
  }

  return NextResponse.next()
}

