import { NextResponse, type NextRequest } from 'next/server'

import { z } from 'zod'

import { contactMessageSchema } from '@/features/contact/schemas/contact.schema'
import { proxyPost } from '@/libs/api/route-handler'
import type { ApiResponse } from '@/types/common'

type ContactFieldErrors = { fieldErrors: Partial<Record<'name' | 'email' | 'message', string[]>> }

// Storage belongs to the upstream service; this route only validates and forwards.
const forwardToUpstream = proxyPost('/v1/contact-messages')

/**
 * Public contact-form endpoint. Validates the message on the server with the
 * shared schema, answers 400 for an unreadable body and 422 with per-field errors
 * for invalid input (the upstream API is never called in either case), and hands
 * a valid message to the upstream API, returning its envelope unchanged.
 */
export async function POST(req: NextRequest) {
  let body: unknown

  try {
    body = await req.json()
  } catch {
    return NextResponse.json(
      {
        success: false,
        code: 'BAD_REQUEST',
        message: 'Data yang dikirim tidak dapat dibaca. Silakan coba lagi.',
        data: null
      } satisfies ApiResponse<null>,
      { status: 400 }
    )
  }

  const parsed = contactMessageSchema.safeParse(body)

  if (!parsed.success) {
    return NextResponse.json(
      {
        success: false,
        code: 'VALIDATION_ERROR',
        message: 'Pesan belum terkirim. Periksa kembali nama, email, dan pesan Anda.',
        data: { fieldErrors: z.flattenError(parsed.error).fieldErrors }
      } satisfies ApiResponse<ContactFieldErrors>,
      { status: 422 }
    )
  }

  // Rebuild the request so only the validated, trimmed fields reach the upstream
  // API — never the raw browser body.
  const { name, email, message } = parsed.data

  const forwarded = new NextRequest(req.url, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ name, email, message })
  })

  return forwardToUpstream(forwarded)
}

