import { http, HttpResponse } from 'msw'
import { NextRequest } from 'next/server'
import { describe, expect, it, vi } from 'vitest'

import { server } from '@/test/handlers'

import { POST } from './route'

// apiServer reads the session through getServerSession; the public contact route
// has no signed-in user, so the upstream call goes out without a bearer token.
vi.mock('next-auth', () => ({ getServerSession: vi.fn(async () => null) }))

const UPSTREAM_URL = 'http://localhost:3000/v1/contact-messages'
const ROUTE_URL = 'http://localhost:3000/api/v1/contact-messages'

const upstreamOk = {
  success: true,
  code: 'CREATED',
  message: 'Contact message stored',
  data: { id: 1 }
}

type ErrorEnvelope = {
  success: boolean
  code: string
  message: string
  data: { fieldErrors: Record<string, string[] | undefined> } | null
}

/** Registers the upstream handler and returns the bodies it receives (one entry per call). */
function captureUpstream(respond: () => Response = () => HttpResponse.json(upstreamOk)) {
  const received: unknown[] = []

  server.use(
    http.post(UPSTREAM_URL, async ({ request }) => {
      received.push(await request.json())

      return respond()
    })
  )

  return received
}

function postRaw(body: string) {
  return POST(
    new NextRequest(ROUTE_URL, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body
    })
  )
