/** Posts an invalid payload and asserts a 422 validation envelope that never reached upstream. */
async function expectRejected(body: unknown) {
  const received = captureUpstream()
  const res = await postJson(body)
  const json = (await res.json()) as ErrorEnvelope

  expect(res.status).toBe(422)
  expect(json.success).toBe(false)
  expect(json.code).toBe('VALIDATION_ERROR')
  expect(json.message).toEqual(expect.any(String))
  expect(received).toHaveLength(0)

  return json.data?.fieldErrors ?? {}
}

