describe('POST /api/v1/contact-messages', () => {
  it('forwards a valid message to POST /v1/contact-messages and returns the upstream envelope', async () => {
    const received = captureUpstream()

    const res = await postJson(valid)

    expect(res.status).toBe(200)
    expect(await res.json()).toEqual(upstreamOk)
    expect(received).toEqual([valid])
  })

  it('rejects an invalid email with a field error for email', async () => {
    const fieldErrors = await expectRejected({ ...valid, email: 'bukan-email' })

    expect(fieldErrors.email?.length).toBeGreaterThan(0)
    expect(fieldErrors.name).toBeUndefined()
    expect(fieldErrors.message).toBeUndefined()
  })

  it('rejects an empty or longer-than-100-character name', async () => {
    expect((await expectRejected({ ...valid, name: '' })).name?.length).toBeGreaterThan(0)
    expect((await expectRejected({ ...valid, name: 'a'.repeat(101) })).name?.length).toBeGreaterThan(0)
  })

  it('rejects an empty or longer-than-2000-character message', async () => {
    expect((await expectRejected({ ...valid, message: '' })).message?.length).toBeGreaterThan(0)
    expect((await expectRejected({ ...valid, message: 'm'.repeat(2001) })).message?.length).toBeGreaterThan(0)
  })

  it('accepts a 100-character name and a 2000-character message', async () => {
    const received = captureUpstream()
    const boundary = { ...valid, name: 'a'.repeat(100), message: 'm'.repeat(2000) }

    const res = await postJson(boundary)

    expect(res.status).toBe(200)
    expect(received).toEqual([boundary])
  })

  it('does not call the upstream API when validation fails', async () => {
    const fieldErrors = await expectRejected({ name: '', email: 'x', message: '' })

    expect(Object.keys(fieldErrors).sort()).toEqual(['email', 'message', 'name'])
  })

  it('rejects a whitespace-only name and message', async () => {
    const fieldErrors = await expectRejected({ ...valid, name: '   ', message: ' \n\t ' })

    expect(fieldErrors.name?.length).toBeGreaterThan(0)
    expect(fieldErrors.message?.length).toBeGreaterThan(0)
  })

  it('rejects an email longer than 255 characters', async () => {
    const fieldErrors = await expectRejected({ ...valid, email: emailOfLength(256) })

    expect(fieldErrors.email?.length).toBeGreaterThan(0)

    // The same shape one character shorter is accepted, so the length is what failed.
    const received = captureUpstream()
    const res = await postJson({ ...valid, email: emailOfLength(255) })

    expect(res.status).toBe(200)
    expect(received).toHaveLength(1)
  })

  it('does not forward extra unknown fields to the upstream API', async () => {
    const received = captureUpstream()

    const res = await postJson({ ...valid, id: 99, isAdmin: true, created_at: '2020-01-01T00:00:00Z' })

    expect(res.status).toBe(200)
    expect(received).toEqual([valid])
  })

  it('trims surrounding whitespace before forwarding', async () => {
    const received = captureUpstream()

    const res = await postJson({ name: `  ${valid.name} `, email: ` ${valid.email}  `, message: `\n${valid.message}\n` })

    expect(res.status).toBe(200)
    expect(received).toEqual([valid])
  })

  it('returns a structured error instead of crashing on a malformed JSON body', async () => {
    const received = captureUpstream()

    const res = await postRaw('{"name": "Budi",')
    const json = (await res.json()) as ErrorEnvelope

    expect(res.status).toBe(400)
    expect(json).toMatchObject({ success: false, code: 'BAD_REQUEST', data: null })
    expect(json.message).toEqual(expect.any(String))
    expect(received).toHaveLength(0)
  })

  it('returns a non-2xx status when the upstream API responds with a failure envelope', async () => {
    const failure = { success: false, code: 'STORE_FAILED', message: 'Could not store the message', data: null }

    // Upstream answers with an HTTP error status.
    captureUpstream(() => HttpResponse.json(failure, { status: 500 }))
    const httpError = await postJson(valid)

