    captureUpstream(() => HttpResponse.json(failure))
    const envelopeError = await postJson(valid)

    expect(envelopeError.ok).toBe(false)
    expect(await envelopeError.json()).toMatchObject({ success: false, code: 'STORE_FAILED' })
  })
})

