export async function POST(req: NextRequest) {
  let body: unknown

  try {
    body = await req.json()
  } catch {
    return NextResponse.json(
      {
        success: false,
        code: 'BAD_REQUEST',
        message: 'Data yang dikirim tidak dapat dibaca. Silakan coba lagi.',
        data: null
      } satisfies ApiResponse<null>,
      { status: 400 }
    )
  }

  const parsed = contactMessageSchema.safeParse(body)

  if (!parsed.success) {
    return NextResponse.json(
      {
        success: false,
        code: 'VALIDATION_ERROR',
        message: 'Pesan belum terkirim. Periksa kembali nama, email, dan pesan Anda.',
        data: { fieldErrors: z.flattenError(parsed.error).fieldErrors }
