  return screen.getByRole('region', { name: 'Profil singkat' })
}

function getTeamItems() {
  return within(screen.getByRole('list', { name: 'Tim' })).getAllByRole('listitem')
}

describe('Tentang Kami page', () => {
  afterEach(() => {
    vi.doUnmock(CONFIG_MODULE)
    vi.resetModules()
  })

  it('renders the profile paragraphs from the config', () => {
    renderWithProviders(<TentangKamiPage />)

    expect(screen.getByRole('heading', { level: 1, name: 'Tentang Kami' })).toBeInTheDocument()

    const region = getProfileRegion()
    const { paragraphs } = companyProfileConfig.about

    expect(region.querySelectorAll('p')).toHaveLength(paragraphs.length)

    paragraphs.forEach(text => {
      expect(within(region).getByText(text).tagName).toBe('P')
    })
  })

  it('lists every team member with name and role', () => {
    renderWithProviders(<TentangKamiPage />)

    const items = getTeamItems()

    expect(items).toHaveLength(companyProfileConfig.team.length)

    items.forEach((item, index) => {
      const member = companyProfileConfig.team[index]

      expect(within(item).getByRole('heading', { level: 3, name: member.name })).toBeInTheDocument()
      expect(within(item).getByText(member.role)).toBeInTheDocument()
    })
  })

  it('links back to /beranda', () => {
    renderWithProviders(<TentangKamiPage />)

    expect(screen.getByRole('link', { name: 'Kembali ke Beranda' })).toHaveAttribute('href', '/beranda')
  })

  it('renders no images for team members', () => {
    const { container } = renderWithProviders(<TentangKamiPage />)

    const teamList = screen.getByRole('list', { name: 'Tim' })

    // No photo and no placeholder avatar of any kind: no <img>, no img role, no MUI Avatar.
    expect(container.querySelectorAll('img')).toHaveLength(0)
    expect(within(teamList).queryAllByRole('img')).toHaveLength(0)
    expect(teamList.querySelectorAll('.MuiAvatar-root')).toHaveLength(0)
  })

  it('renders whatever the config holds instead of hard-coded copy', async () => {
    const alternateConfig: CompanyProfileConfig = {
      organizationName: 'Koperasi Uji Coba Nusantara',
      tagline: 'Tagline pengganti yang hanya ada di test ini.',
      services: [
        { title: 'Layanan Uji Alfa', description: 'Deskripsi uji alfa.' },
        { title: 'Layanan Uji Beta', description: 'Deskripsi uji beta.' },
        { title: 'Layanan Uji Gama', description: 'Deskripsi uji gama.' }
      ],
      about: {
        paragraphs: ['Paragraf profil uji pertama.', 'Paragraf profil uji kedua.']
      },
      team: [
        { name: 'Penguji Satu', role: 'Peran Uji Pertama' },
        { name: 'Penguji Dua', role: 'Peran Uji Kedua' }
      ]
    }

    // Per-test module swap: the page is re-imported after the mock is registered so it
    // picks up the alternate values, while the other tests keep the real config.
    vi.resetModules()
    vi.doMock(CONFIG_MODULE, () => ({ default: alternateConfig }))

    const { default: MockedTentangKamiPage } = await import('./page')

    renderWithProviders(<MockedTentangKamiPage />)

    const region = getProfileRegion()

    expect(region.querySelectorAll('p')).toHaveLength(alternateConfig.about.paragraphs.length)
    alternateConfig.about.paragraphs.forEach(text => {
      expect(within(region).getByText(text)).toBeInTheDocument()
    })

    const items = getTeamItems()

    expect(items).toHaveLength(alternateConfig.team.length)
    alternateConfig.team.forEach((member, index) => {
      expect(within(items[index]).getByRole('heading', { level: 3, name: member.name })).toBeInTheDocument()
      expect(within(items[index]).getByText(member.role)).toBeInTheDocument()
    })

    companyProfileConfig.about.paragraphs.forEach(text => {
      expect(screen.queryByText(text)).not.toBeInTheDocument()
    })
    companyProfileConfig.team.forEach(member => {
      expect(screen.queryByText(member.name)).not.toBeInTheDocument()
      expect(screen.queryByText(member.role)).not.toBeInTheDocument()
    })
  })
})

