import { describe, expect, it } from 'vitest'

import { http, HttpResponse } from 'msw'

import { server } from '@/test/handlers'
import { fireEvent, renderWithProviders, screen, waitFor } from '@/test/utils'

import ContactForm from './index'

// apiClient goes through the same-origin proxy, so the browser-side request lands here.
const CONTACT_URL = 'http://localhost:3000/api/v1/contact-messages'

const SERVER_REJECTION = 'Pesan belum terkirim. Periksa kembali nama, email, dan pesan Anda.'

function getFields() {
  return {
    name: screen.getByRole('textbox', { name: 'Nama' }),
    email: screen.getByRole('textbox', { name: 'Email' }),
    message: screen.getByRole('textbox', { name: 'Pesan' })
  }
}

function getSubmit() {
  return screen.getByRole('button', { name: 'Kirim' })
}

/** Registers a handler for the contact endpoint and records every body it receives. */
function captureRequests(respond: () => Response = () => HttpResponse.json(okEnvelope())) {
  const bodies: unknown[] = []

  server.use(
    http.post(CONTACT_URL, async ({ request }) => {
      bodies.push(await request.json())

      return respond()
    })
  )

  return bodies
}

function okEnvelope() {
  return { success: true, code: 'OK', message: 'ok', data: null }
}

describe('ContactForm', () => {
  it('shows Pesan terkirim on the same page after a successful submit', async () => {
    const bodies = captureRequests()
    const { user } = renderWithProviders(<ContactForm />)
    const fields = getFields()

    await user.type(fields.name, 'Budi Santoso')
    await user.type(fields.email, 'budi@example.com')
    await user.type(fields.message, 'Halo, saya ingin bertanya tentang layanan Anda.')
    await user.click(getSubmit())

    expect(await screen.findByText('Pesan terkirim')).toBeInTheDocument()
    expect(bodies).toEqual([
      { name: 'Budi Santoso', email: 'budi@example.com', message: 'Halo, saya ingin bertanya tentang layanan Anda.' }
    ])

    // The form stays on the page, ready for another message.
    expect(getSubmit()).toBeInTheDocument()
  })

  it('shows an error on the email field for an invalid email', async () => {
    captureRequests()
    const { user } = renderWithProviders(<ContactForm />)
    const fields = getFields()

    await user.type(fields.name, 'Budi')
    await user.type(fields.email, 'bukan-email')
    await user.type(fields.message, 'Halo')
    await user.click(getSubmit())

    await waitFor(() => expect(fields.email).toHaveAttribute('aria-invalid', 'true'))
    expect(fields.email).toHaveAccessibleDescription('Format email tidak valid')
    expect(fields.name).toHaveAttribute('aria-invalid', 'false')
    expect(fields.message).toHaveAttribute('aria-invalid', 'false')
  })

  it('shows errors on the name and message fields when they are empty or too long', async () => {
    captureRequests()
    const { user } = renderWithProviders(<ContactForm />)
    const fields = getFields()

    await user.type(fields.email, 'budi@example.com')
    await user.click(getSubmit())

    await waitFor(() => expect(fields.name).toHaveAccessibleDescription('Nama wajib diisi'))
    expect(fields.message).toHaveAccessibleDescription('Pesan wajib diisi')

    // Whitespace-only counts as empty.
    fireEvent.change(fields.name, { target: { value: '   ' } })
    await user.click(getSubmit())
    await waitFor(() => expect(fields.name).toHaveAccessibleDescription('Nama wajib diisi'))

    fireEvent.change(fields.name, { target: { value: 'a'.repeat(101) } })
    fireEvent.change(fields.message, { target: { value: 'b'.repeat(2001) } })
    await user.click(getSubmit())

    await waitFor(() => expect(fields.name).toHaveAccessibleDescription('Nama maksimal 100 karakter'))
    expect(fields.message).toHaveAccessibleDescription('Pesan maksimal 2000 karakter')
    expect(fields.name).toHaveAttribute('aria-invalid', 'true')
    expect(fields.message).toHaveAttribute('aria-invalid', 'true')
  })

  it('keeps the entered values after a failed validation', async () => {
    captureRequests()
    const { user } = renderWithProviders(<ContactForm />)
    const fields = getFields()

    await user.type(fields.name, 'Budi Santoso')
    await user.type(fields.email, 'budi@')
    await user.type(fields.message, 'Pesan saya tetap ada.')
    await user.click(getSubmit())

    await waitFor(() => expect(fields.email).toHaveAttribute('aria-invalid', 'true'))
    expect(fields.name).toHaveValue('Budi Santoso')
    expect(fields.email).toHaveValue('budi@')
    expect(fields.message).toHaveValue('Pesan saya tetap ada.')
  })

  it('gives every field an accessible label', async () => {
    const { user } = renderWithProviders(<ContactForm />)
    const fields = getFields()

    // Each label is a visible <label> element tied to its input.
    for (const [input, text] of [
      [fields.name, 'Nama'],
      [fields.email, 'Email'],
      [fields.message, 'Pesan']
    ] as const) {
      const label = document.querySelector(`label[for="${input.id}"]`)

      expect(label).not.toBeNull()
      expect(label).toHaveTextContent(text)
    }

    expect(fields.message.tagName).toBe('TEXTAREA')

    // Tab order follows the visual order and ends on the submit button.
    await user.tab()
    expect(fields.name).toHaveFocus()
    await user.tab()
    expect(fields.email).toHaveFocus()
    await user.tab()
    expect(fields.message).toHaveFocus()
    await user.tab()
    expect(getSubmit()).toHaveFocus()
  })

  it('does not send a request when validation fails', async () => {
    const bodies = captureRequests()
    const { user } = renderWithProviders(<ContactForm />)

    await user.click(getSubmit())

    await waitFor(() => expect(getFields().name).toHaveAccessibleDescription('Nama wajib diisi'))
    expect(bodies).toHaveLength(0)
    expect(screen.queryByText('Pesan terkirim')).not.toBeInTheDocument()
  })

  it('keeps the entered values and shows the server message when the server rejects the submission', async () => {
    const bodies = captureRequests(() =>
      HttpResponse.json(
        { success: false, code: 'VALIDATION_ERROR', message: SERVER_REJECTION, data: { fieldErrors: {} } },
        { status: 422 }
      )
    )

    const { user } = renderWithProviders(<ContactForm />)
    const fields = getFields()
    const hostileName = '<img src=x onerror="alert(1)">'

    fireEvent.change(fields.name, { target: { value: hostileName } })
    await user.type(fields.email, 'budi@example.com')
    await user.type(fields.message, 'Tolong hubungi saya.')
    await user.click(getSubmit())

    expect(await screen.findByText(SERVER_REJECTION)).toBeInTheDocument()
    expect(bodies).toHaveLength(1)
    expect(screen.queryByText('Pesan terkirim')).not.toBeInTheDocument()

    expect(fields.name).toHaveValue(hostileName)
    expect(fields.email).toHaveValue('budi@example.com')
    expect(fields.message).toHaveValue('Tolong hubungi saya.')

    // Visitor input stays text: nothing it contains is turned into markup.
    expect(document.querySelector('img')).toBeNull()
  })
})

