// MUI Imports
import Alert from '@mui/material/Alert'
import Button from '@mui/material/Button'
import Stack from '@mui/material/Stack'
import TextField from '@mui/material/TextField'

// Third-party Imports
import { Controller, useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'

// Feature Imports
import {
  contactMessageDefaults,
  contactMessageSchema,
  type ContactMessageValues
} from '../../schemas/contact.schema'
import { useContactMessage } from '../../hooks/useContactMessage'

/**
 * Public contact form: name, email and message. The browser checks input with the
 * same schema the server uses, so a visitor sees per-field errors before anything is
 * sent; the server still validates on its own. Success and server errors are shown
 * inline because the public pages have no snackbar host. Every value is rendered as
 * text by React — nothing the visitor types is ever injected as markup.
 */
const ContactForm = () => {
  const { mutate: sendMessage, isPending, isSuccess, error, reset: resetMutation } = useContactMessage()

  const {
    control,
    handleSubmit,
    reset: resetForm,
    formState: { errors }
  } = useForm<ContactMessageValues>({
    resolver: zodResolver(contactMessageSchema),
    defaultValues: contactMessageDefaults
  })

  const onSubmit = (values: ContactMessageValues) => {
    resetMutation()

    sendMessage(values, {
      // Clear the form only once the message is stored; on a rejection the visitor
      // keeps everything they typed.
      onSuccess: () => resetForm(contactMessageDefaults)
    })
  }

