// Vitest runs the unit/component suites (no Next.js runtime). JSX is transformed by
// Vitest's built-in esbuild via the tsconfig `react-jsx` runtime (no @vitejs/plugin-react
// needed). `vite-tsconfig-paths` reuses the `@/`, `@core/`, … aliases from tsconfig.json
// so test imports match app imports exactly.
export default defineConfig({
  plugins: [tsconfigPaths()],

  // The app's postcss.config.mjs (Tailwind 4) isn't loadable in the Vitest
  // context; bypass it so CSS-module imports (e.g. stepper-dot) resolve to a
  // class-name map without running Tailwind.
  css: {
    postcss: { plugins: [] }
  },
  test: {
    environment: 'jsdom',
    globals: true,
    setupFiles: ['./src/test/setup.ts'],
    css: false,

    // jsdom needs an absolute origin so relative fetches (`/api/...`) and apiClient
    // (NEXT_PUBLIC_API_URL below) resolve to parseable absolute URLs for MSW.
    environmentOptions: {
      jsdom: { url: 'http://localhost:3000' }
    },
    env: {
      NEXT_PUBLIC_API_URL: 'http://localhost:3000'
    },
    include: ['src/**/*.{test,spec}.{ts,tsx}'],
    clearMocks: true
  }
})

import { setupServer } from 'msw/node'
import { http, HttpResponse } from 'msw'

const ORIGIN = 'http://localhost:3000'

const envelope = <T>(data: T, total = Array.isArray(data) ? data.length : 1) => ({
  success: true,
  code: 'OK',
  message: 'ok',
  data,
  meta: { pagination: { total_rows: total } }
})

/**
 * Default MSW handlers for the access-control features shipped with the starter
 * kit. Individual tests override these per-case with `server.use(...)`.
 *
 * apiClient targets the same-origin proxy routes (`/api/v1/...`), so handlers are
 * registered against those paths; the fetch shim in setup.ts prefixes relative
 * URLs with ORIGIN.
 */
export const handlers = [
  http.get(`${ORIGIN}/api/v1/users`, () =>
    HttpResponse.json(
      envelope([
        {
          id: 'u1',
          username: 'jdoe',
          fullName: 'John Doe',
          email: 'jdoe@example.com',
          isActive: true
        }
      ])
    )
  ),

  http.get(`${ORIGIN}/api/v1/users/:id`, ({ params }) =>
    HttpResponse.json(
      envelope({
        id: String(params.id),
        username: 'jdoe',
        fullName: 'John Doe',
        email: 'jdoe@example.com',
        isActive: true
      })
    )
  ),

  http.post(`${ORIGIN}/api/v1/users`, async ({ request }) => {
    const body = (await request.json()) as Record<string, unknown>

    return HttpResponse.json(envelope({ id: 'new-user', ...body }))
  }),

  http.put(`${ORIGIN}/api/v1/users/:id`, async ({ request, params }) => {
    const body = (await request.json()) as Record<string, unknown>

    return HttpResponse.json(envelope({ id: params.id, ...body }))
  }),

  http.delete(`${ORIGIN}/api/v1/users/:id`, ({ params }) => HttpResponse.json(envelope({ id: params.id }))),

  http.get(`${ORIGIN}/api/v1/roles`, () => HttpResponse.json(envelope([{ id: 'r1', name: 'Admin', permissions: [] }]))),

  http.get(`${ORIGIN}/api/v1/permission`, () =>
    HttpResponse.json(envelope([{ id: 'p1', name: 'USER.READ', resource: 'USER', action: 'READ' }]))
  ),

  http.get(`${ORIGIN}/api/v1/branches`, () => HttpResponse.json(envelope([{ id: 'b1', code: '001', name: 'Head Office' }])))
]

export const server = setupServer(...handlers)

